#pragma once

/*
 * Build-time description of a VMM and its guest, generated by the metaprogram
 * (acacia_libvmm/config.py) and objcopied into the VMM's .vmm_config section.
 *
 * This is a serialisation format, not libvmm's API. libvmm itself is
 * configured through arch_guest_init_t, which vmm_config_fill_guest_init()
 * fills from here. If you change the layout, change acacia_libvmm/config.py
 * too.
 */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <string.h>
#include <libvmm/guest.h>
#include <libvmm/guest_ram.h>

#define VMM_MAGIC_LEN 4
static const char VMM_MAGIC[VMM_MAGIC_LEN] = { 'v', 'm', 'm', 0x1 };

#define VMM_MAX_RAM_REGIONS GUEST_MAX_RAM_REGIONS
#define VMM_MAX_IRQS 32
#define VMM_MAX_VCPUS 32
#define VMM_MAX_DT_DEVICES 32
#define VMM_MAX_IOPORTS 16

#define VMM_DT_DEV_NAME_MAX_LEN 32 // Including the NUL terminator

typedef enum vmm_config_ram_kind {
    VMM_CONFIG_RAM = 0,
    VMM_CONFIG_FLASH = 1,
} vmm_config_ram_kind_t;

typedef struct vmm_config_ram_region {
    uint64_t gpa;
    uint64_t size;
    uintptr_t vmm_vaddr;
    /* vmm_config_ram_kind_t */
    uint8_t kind;
} vmm_config_ram_region_t;

typedef struct vmm_config_irq {
    uint8_t id;
    /* GIC INTID on ARM, guest I/O APIC pin on x86 */
    uint32_t irq;
} vmm_config_irq_t;

typedef struct vmm_config_guest_dt_device {
    char name[VMM_DT_DEV_NAME_MAX_LEN];
    uint64_t gpa_base;
    uint32_t size;
    uint64_t vmm_vaddr;
    uint32_t irq;
} vmm_config_guest_dt_device_t;

typedef struct vmm_config_vcpu {
    uint8_t id;
} vmm_config_vcpu_t;

typedef struct vmm_config_ioport {
    uint8_t id;
    uint16_t addr;
    uint16_t size;
} vmm_config_ioport_t;

typedef struct vmm_config {
    char magic[VMM_MAGIC_LEN + 1];
    uint8_t num_ram_regions;
    vmm_config_ram_region_t ram_regions[VMM_MAX_RAM_REGIONS];
    /* Begin DTB guest only fields */
    uint64_t dtb_gpa;
    uint64_t initrd_gpa;
    uint8_t num_dt_devices;
    vmm_config_guest_dt_device_t dt_devices[VMM_MAX_DT_DEVICES];
    /* End DTB guest only fields */
    uint8_t num_irqs;
    vmm_config_irq_t irqs[VMM_MAX_IRQS];
    /* vCPU IDs are always 0 to num_vcpus - 1 */
    uint8_t num_vcpus;
    vmm_config_vcpu_t vcpus[VMM_MAX_VCPUS];
    /* Begin x86 guest only fields */
    uint8_t num_ioports;
    vmm_config_ioport_t ioports[VMM_MAX_IOPORTS];
    /* End x86 guest only fields */
} vmm_config_t;

static inline bool vmm_config_check_magic(const vmm_config_t *config)
{
    for (int i = 0; i < VMM_MAGIC_LEN; i++) {
        if (config->magic[i] != VMM_MAGIC[i]) {
            return false;
        }
    }
    return true;
}

/* Returns the guest IRQ for the passthrough IRQ on channel `id`, or -1 if there is none. */
static inline int vmm_config_irq_from_id(const vmm_config_t *config, uint8_t id)
{
    for (int i = 0; i < config->num_irqs; i++) {
        if (config->irqs[i].id == id) {
            return config->irqs[i].irq;
        }
    }

    return -1;
}

/*
 * Fill in the parts of `args` that the config describes: the guest memory
 * regions and, on ARM, the number of vCPUs. Everything else in `args` is left
 * for the caller to set.
 */
static inline bool vmm_config_fill_guest_init(const vmm_config_t *config, arch_guest_init_t *args)
{
    if (config->num_ram_regions > GUEST_MAX_RAM_REGIONS) {
        return false;
    }

    for (int i = 0; i < config->num_ram_regions; i++) {
        args->guest_ram_regions[i] = (struct guest_ram_region) {
            .gpa_start = config->ram_regions[i].gpa,
            .size = config->ram_regions[i].size,
            .vmm_vaddr = (void *)config->ram_regions[i].vmm_vaddr,
        };
    }
    args->num_guest_ram_regions = config->num_ram_regions;

#if defined(CONFIG_ARCH_ARM)
    args->num_vcpus = config->num_vcpus;
#endif

    return true;
}

static inline const vmm_config_guest_dt_device_t *vmm_config_find_dt_dev_from_name(const vmm_config_t *config,
                                                                                   const char *name)
{
    for (int i = 0; i < config->num_dt_devices; i++) {
        if (strncmp(config->dt_devices[i].name, name, VMM_DT_DEV_NAME_MAX_LEN) == 0) {
            return &config->dt_devices[i];
        }
    }
    return NULL;
}
